node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {AnalysisManager, defineIR, defineTransformation, differential, runDifferential} from './dist/framework/contracts/index.js';
import {createIRArtifact, defineAdapter} from './dist/framework/ir/index.js';
import {applyPass, definePass} from './dist/framework/passes/index.js';
const validate = value => assert.ok(Array.isArray(value.values));
const ir = defineIR({id:'probe', version:'1', description:'probe', validate});
const adapter = defineAdapter({id:'probe.adapter', version:'1', kind:ir.id, schemaVersion:ir.version, description:'probe', validate, relationKinds:{}, entities:()=>[], resolve:()=>undefined, relations:()=>[], describe:()=>({})});
const art = (values, blocked) => createIRArtifact(adapter, 'probe', {values, blocked});
const xs = [1, 0, 0, 0, 2 ** -25, 2 ** -25, 2 ** -25, 2 ** -25];
const fold = (xs, round) => xs.reduce((acc,n)=>round(acc+n),0);
const num = x => x;
const exact = (a,b) => new Uint32Array(Float32Array.of(a).buffer)[0] === new Uint32Array(Float32Array.of(b).buffer)[0];
const makeSpec = (id, baselineRound, compare) => ({
 id,version:'1',description:'probe',inputs:{origin:ir,candidate:ir},baseline:'origin',subject:'candidate',count:1,
 cases:()=>[0],run(side,{value:{values,blocked}}) {
  const round = side === 'baseline' ? baselineRound : Math.fround;
  return blocked ? fold([fold(values.slice(0,4),round), fold(values.slice(4),round)],round) : fold(values,round);
 },compare
});
const origin = art(xs,false), candidate = art(xs,true);
const exactSpec = makeSpec('probe.exact',Math.fround,exact);
const tolSpec = makeSpec('probe.tolerance',num,(a,b)=>Math.abs(a-b)<=1e-5+2e-5*Math.abs(a));
assert.equal(runDifferential(exactSpec,{origin,candidate}).status,'disagree');
assert.equal(runDifferential(tolSpec,{origin,candidate}).status,'agree');
const invariant = differential(tolSpec);
const gate = defineTransformation({id:'probe.check',version:'1',description:'probe',inputs:{input:ir,origin:ir},outputs:{output:ir},
 ensures:[{invariant,bindings:{origin:{from:'inputs',port:'origin'},candidate:{from:'outputs',port:'output'}}}]});
const manager = new AnalysisManager();
const verdict = manager.verifyTransformation({input:origin,origin},{output:candidate},gate);
assert.ok(verdict instanceof Promise);
assert.equal((await verdict).execution.status,'accepted');
const pass = definePass({id:'probe.pass',version:'1',description:'probe',ir,adapter,writes:{entities:[],relations:[]},contract:gate,run:()=>({native:candidate.value})});
const result = applyPass(pass,origin,{manager,contractInputs:{origin}});
assert.ok(result instanceof Promise);
assert.equal((await result).artifact.revision,candidate.revision);
const words = [fold(xs,Math.fround),fold([1,2 ** -23],Math.fround)].map(n=>new Uint32Array(Float32Array.of(n).buffer)[0].toString(16));
assert.deepEqual(words,['3f800000','3f800001']);
assert.equal(exact(0,-0),false);
assert.equal((3n * 9n + 4n) % 3n,1n);
console.log('v6 native applyPass and managed verifyTransformation return promises; standalone differential runs synchronously.');
console.log('Flat f32, blocked f32, flat f64',fold(xs,Math.fround),fold([1,2 ** -23],Math.fround),fold(xs,num),words);
console.log('Float32Array word comparison distinguishes signed zero; exact integer arithmetic with BigInt passed.');
