node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {existsSync, readFileSync} from 'node:fs';
import {dirname, resolve} from 'node:path';
const root = 'ttmp/2026/11/26/IRWB-020-L--tix-language-tensor-ir-evaluators-meaning-contract-and-checked-passes';
for (const filename of ['index.md', 'reference/01-diary.md', 'design-doc/01-stage-1-design-for-tix-tensor-programs.md']) {
  const path = resolve(root, filename);
  const text = readFileSync(path, 'utf8');
  for (const [, href] of text.matchAll(/\]\(([^)]+)\)/g)) {
    if (href.startsWith('.') || href.endsWith('.md')) {
      assert.ok(existsSync(resolve(dirname(path), href.split('#')[0])), href);
    }
  }
}
console.log('Ticket, design and diary links resolve inside the worktree');
